/*
 * Standalone compile model (NOT a kernel build).
 *
 * Reproduces the exact new code text of the candidate against minimal stubs
 * that match the target 5.15.7 signatures, to syntax/type-check the new lines
 * with -Wall -Werror. It is not a substitute for building kernel/sched/wait.o.
 */
#include <stdint.h>

typedef uint32_t __poll_t;

#define __force
#define TASK_NORMAL 3
#define POLLHUP  0x0010
#define POLLFREE ((__force __poll_t)0x4000)

#define poll_to_key(m) ((void *)(__force uintptr_t)(__poll_t)(m))

struct wait_queue_head {
	int dummy;
};

static inline int waitqueue_active(struct wait_queue_head *wq_head)
{
	return wq_head->dummy;
}

extern void __wake_up(struct wait_queue_head *wq_head, unsigned int mode,
		      int nr, void *key);

#define WARN_ON_ONCE(condition) do { (void)(condition); } while (0)
#define __wake_up_pollfree __wake_up_pollfree_model
#define wake_up_pollfree wake_up_pollfree_model

/* --- begin: copied from candidate kernel/sched/wait.c --- */
void __wake_up_pollfree_model(struct wait_queue_head *wq_head)
{
	__wake_up(wq_head, TASK_NORMAL, 0, poll_to_key(POLLHUP | POLLFREE));
	/* POLLFREE must have cleared the queue. */
	WARN_ON_ONCE(waitqueue_active(wq_head));
}
/* --- end: copied from candidate kernel/sched/wait.c --- */

/* --- begin: copied from candidate include/linux/wait.h --- */
static inline void wake_up_pollfree_model(struct wait_queue_head *wq_head)
{
	if (waitqueue_active(wq_head))
		__wake_up_pollfree_model(wq_head);
}
/* --- end: copied from candidate include/linux/wait.h --- */

int main(void)
{
	struct wait_queue_head wq = { 0 };

	wake_up_pollfree_model(&wq);
	return 0;
}

