/*
 * Standalone model test (NOT a kernel build).
 *
 * Mirrors the target 5.15.7 definitions the candidate relies on:
 *  - include/uapi/asm-generic/poll.h: POLLIN, POLLHUP, POLLFREE
 *  - include/linux/wait.h:            poll_to_key(), key_to_poll()
 *
 * It verifies the security-relevant key round trip used by the ported
 * __wake_up_pollfree(): the produced key must decode back to POLLHUP|POLLFREE,
 * and an unrelated mask must not gain the POLLFREE bit.
 */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>

typedef uint32_t __poll_t;

#define POLLIN   0x0001
#define POLLHUP  0x0010
#define POLLFREE 0x4000

#define poll_to_key(m) ((void *)(uintptr_t)(__poll_t)(m))
#define key_to_poll(m) ((__poll_t)(uintptr_t)(void *)(m))

int main(void)
{
	__poll_t mask = POLLHUP | POLLFREE;
	void *key = poll_to_key(mask);
	__poll_t back = key_to_poll(key);

	/* positive: POLLFREE survives the wake key and is recoverable */
	assert(back == mask);
	assert(back & POLLFREE);
	assert((back & POLLHUP) == POLLHUP);

	/* negative: an unrelated mask must not carry POLLFREE */
	assert(!(key_to_poll(poll_to_key((__poll_t)POLLIN)) & POLLFREE));

	printf("ok: key=0x%lx back=0x%x\n",
	       (unsigned long)(uintptr_t)key, (unsigned)back);
	return 0;
}

